// Universe Management & Dynamic Storage Helpers
window.getActiveUniverse = function() {
  try {
    const u = localStorage.getItem('active_card_universe');
    if (u && ['sololeveling', 'naruto', 'onepiece', 'multiverse'].includes(u)) {
      return u;
    }
  } catch (e) {
    console.warn('Failed to get active universe:', e);
  }
  return 'sololeveling';
};

window.setActiveUniverse = function(universe) {
  try {
    if (['sololeveling', 'naruto', 'onepiece', 'multiverse'].includes(universe)) {
      localStorage.setItem('active_card_universe', universe);
    }
  } catch (e) {
    console.error('Failed to set active universe:', e);
  }
};

window.getStoredCharacters = function(universe) {
  const activeUni = universe || window.getActiveUniverse();
  const storageKey = 'custom_roster_' + activeUni;
  
  try {
    const saved = localStorage.getItem(storageKey);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed;
      }
    }
  } catch (e) {
    console.warn('Failed to load custom roster for ' + activeUni + ':', e);
  }

  // Fallback to defaults
  if (activeUni === 'naruto') {
    return JSON.parse(JSON.stringify(window.DEFAULT_NARUTO_CHARACTERS));
  } else if (activeUni === 'onepiece') {
    return JSON.parse(JSON.stringify(window.DEFAULT_ONEPIECE_CHARACTERS));
  } else if (activeUni === 'multiverse') {
    return JSON.parse(JSON.stringify(window.DEFAULT_ALL_CHARACTERS));
  }
  return JSON.parse(JSON.stringify(window.DEFAULT_SOLO_CHARACTERS));
};

window.saveStoredCharacters = function(universe, roster) {
  const activeUni = universe || window.getActiveUniverse();
  const storageKey = 'custom_roster_' + activeUni;
  try {
    localStorage.setItem(storageKey, JSON.stringify(roster));
  } catch (e) {
    console.error('Failed to save custom roster for ' + activeUni + ':', e);
  }
};

window.resetUniverseRoster = function(universe) {
  const activeUni = universe || window.getActiveUniverse();
  const storageKey = 'custom_roster_' + activeUni;
  try {
    localStorage.removeItem(storageKey);
  } catch (e) {
    console.warn('Failed to remove custom roster for ' + activeUni + ':', e);
  }
  return window.getStoredCharacters(activeUni);
};